import { createServer } from 'node:http'
import { Readable } from 'node:stream'
import unpipe from 'unpipe'

export class Broadcaster {
  #source
  #destinations = new Set()

  constructor(source) {
    this.#source = source
  }

  get source() {
    return this.#source
  }

  get size() {
    return this.#destinations.size
  }

  add(destination) {
    if (this.#destinations.has(destination)) return destination

    this.#destinations.add(destination)
    destination.once('close', () => this.remove(destination))
    this.#source.pipe(destination, { end: false })
    return destination
  }

  remove(destination) {
    if (!this.#destinations.delete(destination)) return false
    this.#source.unpipe(destination)
    return true
  }

  unpipeAll() {
    const count = this.#destinations.size
    this.#destinations.clear()
    unpipe(this.#source)
    return count
  }
}

export function ticker(intervalMs = 1000) {
  let tick = 0
  return new Readable({
    objectMode: true,
    read() {
      tick += 1
      this.push({ tick, at: Date.now() })
    },
    destroy(error, callback) {
      clearInterval(timer)
      callback(error)
    },
  })
}

export function createStreamServer({ intervalMs = 1000 } = {}) {
  const source = ticker(intervalMs)
  const broadcaster = new Broadcaster(source)

  const server = createServer((req, res) => {
    if (req.url === '/stop') {
      const dropped = broadcaster.unpipeAll()
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ unpiped: dropped }))
      return
    }

    res.writeHead(200, {
      'content-type': 'application/x-ndjson',
      'cache-control': 'no-cache',
      connection: 'keep-alive',
    })

    const onData = (chunk) => {
      if (!res.write(`${JSON.stringify(chunk)}\n`)) source.pause()
      res.once('drain', () => source.resume())
    }
    source.on('data', onData)
    broadcaster.add(res)
    res.once('close', () => source.off('data', onData))
  })

  server.on('close', () => broadcaster.unpipeAll())

  return { server, broadcaster, source }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { server, broadcaster, source } = createStreamServer()
  const port = Number(process.env.PORT ?? 3000)

  server.listen(port, () => {
    console.log(`listening on http://localhost:${port}`)
    console.log('GET /      stream ticks')
    console.log('GET /stop  unpipe the source from all destinations')
  })

  const shutdown = () => {
    broadcaster.unpipeAll()
    source.destroy()
    server.close(() => process.exit(0))
  }
  process.on('SIGINT', shutdown)
  process.on('SIGTERM', shutdown)
}

part.text:
Wait, there's a bug in the ticker: I used `read()` that pushes on each read but no interval; and a `clearInterval(timer)` referencing undefined timer. Also the design: I want a ticker that emits periodically. A Readable in object mode with read() pushing once per read is fine (pull-based). But the intervalMs param is unused. Let me simplify: use setInterval to push ticks, or use the pull model.

Actually, the mixing of `source.on('data', onData)` plus `source.pipe(destination)` is problematic: when you attach a 'data' listener and also pipe, both consume. The piped destinations get the data via pipe; the onData backpressure handling adds a second data listener. That's messy.

Let me redesign more cleanly:
- Broadcaster.pipe(dest) uses source.pipe(dest, {end:false}).
- Backpressure: Node's pipe handles backpressure per destination? With multiple destinations, pipe pauses source when any destination returns false and resumes when all drain (Node handles this). So I don't need manual onData. Good—remove the onData logic.

Let me also fix the ticker to be periodic and clear on destroy.

But periodic push with objectMode: 
